// TestWriteGuardEmitsJSONForFailedWrites verifies that a failed write
// (error present in ToolResult) produces a JSON event with type "write_guard"
// so downstream consumers can detect and alert on write failures.
func TestWriteGuardEmitsJSONForFailedWrites(t *testing.T) {
	var buf bytes.Buffer
	m := &Model{}
	m.SetJSONEventStream(&buf, "sess-guard")

	m.recordWriteFailure(5,
		workspace.ToolRequest{Tool: "write_file", Path: "pkg/main.go", Description: "add entrypoint"},
		workspace.ToolResult{Tool: "write_file", Error: "permission denied"},
	)

	events := decodeJSONEvents(t, buf.String())
	if len(events) != 1 {
		t.Fatalf("expected 1 guard event, got %d: %v", len(events), events)
	}
	e := events[0]
	if e["type"] != "write_guard" {
		t.Errorf("type = %q, want %q", e["type"], "write_guard")
	}
	if e["step"] != float64(5) {
		t.Errorf("step = %v, want 5", e["step"])
	}
	if e["tool"] != "write_file" {
		t.Errorf("tool = %q, want %q", e["tool"], "write_file")
	}
	if e["error"] != "permission denied" {
		t.Errorf("error = %q, want %q", e["error"], "permission denied")
	}
}

// TestWriteGuardSuppressesSuccessfulWrites ensures a successful write
// does NOT emit a guard event, keeping the stream uncluttered.
func TestWriteGuardSuppressesSuccessfulWrites(t *testing.T) {
	var buf bytes.Buffer
	m := &Model{}
	m.SetJSONEventStream(&buf, "sess-quiet")

	m.recordWriteSuccess(3,
		workspace.ToolRequest{Tool: "edit_file", Path: "x.go"},
		workspace.ToolResult{Tool: "edit_file", Summary: "ok"},
	)

	events := decodeJSONEvents(t, buf.String())
	if len(events) != 0 {
		t.Fatalf("expected no guard events for success, got %d: %v", len(events), events)
	}
}

// TestWriteGuardNilModelIsSafe verifies that calling recordWriteFailure
// on a nil Model does not panic.
func TestWriteGuardNilModelIsSafe(t *testing.T) {
	defer func() {
		if r := recover(); r != nil {
			t.Fatalf("nil model should not panic; recovered: %v", r)
		}
	}()
	var m *Model
	m.recordWriteFailure(1, workspace.ToolRequest{Tool: "write_file"}, workspace.ToolResult{Error: "boom"})
}

// TestWriteGuardNilEventStreamIsSafe verifies that a model with a nil
