// ── Plan-line rendering regression tests ────────────────────────────────

// TestRenderPlanLineUncheckedTodoRendersMutedBox verifies that an
// unchecked checkbox renders with a muted [ ] indicator.
func TestRenderPlanLineUncheckedTodoRendersMutedBox(t *testing.T) {
	got := renderPlanLine("- [ ] do something", 40)
	if !strings.Contains(got, "[ ]") {
		t.Errorf("expected [ ] marker in rendered line: %q", got)
	}
}

// TestRenderPlanLineCheckedTodoRendersBoldBox verifies that a checked
