func TestRenderPlanLineCheckedTodoRendersBoldBox(t *testing.T) {
	got := renderPlanLine("- [x] done thing", 40)
	if !strings.Contains(got, "[x]") {
		t.Errorf("expected [x] marker in rendered line: %q", got)
	}
}

// TestRenderPlanLineStarUncheckedRecognized verifies that star-bullet
// unchecked items are also recognized as todos.
func TestRenderPlanLineStarUncheckedRecognized(t *testing.T) {
	got := renderPlanLine("* [ ] starred todo", 40)
	if !strings.Contains(got, "[ ]") {
		t.Errorf("star-bullet unchecked not recognized: %q", got)
	}
}

// TestRenderPlanLineStarCheckedRecognized verifies that star-bullet
// checked items are also recognized as done.
func TestRenderPlanLineStarCheckedRecognized(t *testing.T) {
	got := renderPlanLine("* [X] starred done", 40)
	if !strings.Contains(got, "[x]") {
		t.Errorf("star-bullet checked not recognized: %q", got)
	}
}

// TestRenderPlanLineH1RendersAsHeading verifies that a # heading is
// rendered as an H1 plan heading style.
func TestRenderPlanLineH1RendersAsHeading(t *testing.T) {
	got := renderPlanLine("# Session Overview", 40)
	if !strings.Contains(got, "Session Overview") {
		t.Errorf("H1 heading text dropped: %q", got)
	}
}

// TestRenderPlanLineH2RendersAsSubheading verifies that a ## heading is
// rendered as an H2 plan subheading style.
func TestRenderPlanLineH2RendersAsSubheading(t *testing.T) {
	got := renderPlanLine("## Planned", 40)
	if !strings.Contains(got, "Planned") {
		t.Errorf("H2 heading text dropped: %q", got)
	}
}

// TestRenderPlanLineH3RendersAsSubSubheading verifies that a ### heading
// is rendered as an H3 plan sub-subheading style.
func TestRenderPlanLineH3RendersAsSubSubheading(t *testing.T) {
	got := renderPlanLine("### Tasks", 40)
	if !strings.Contains(got, "Tasks") {
		t.Errorf("H3 heading text dropped: %q", got)
	}
}

// TestRenderPlanLinePlainTextRendersPlain verifies that a non-checkbox,
// non-heading line renders as plain panel detail.
func TestRenderPlanLinePlainTextRendersPlain(t *testing.T) {
	got := renderPlanLine("Some prose line", 40)
	if !strings.Contains(got, "Some prose line") {
		t.Errorf("plain text dropped: %q", got)
	}
}

// TestRenderPlanLineStripsHTMLAnchors verifies that HTML comment anchors
// (used for click-to-diff) are stripped from the rendered output.
func TestRenderPlanLineStripsHTMLAnchors(t *testing.T) {
	got := renderPlanLine("- [ ] task <!-- id:abc123 -->", 40)
	if strings.Contains(got, "abc123") {
		t.Errorf("HTML anchor leaked into rendered output: %q", got)
	}
	if !strings.Contains(got, "[ ]") {
		t.Errorf("checkbox marker dropped after anchor strip: %q", got)
	}
	if !strings.Contains(got, "task") {
		t.Errorf("task text dropped after anchor strip: %q", got)
	}
}

// TestRenderPlanLinePreservesIndent verifies that leading whitespace
// (indentation) is preserved in the rendered output.
func TestRenderPlanLinePreservesIndent(t *testing.T) {
	got := renderPlanLine("  - [ ] indented task", 40)
	if !strings.Contains(got, "  - [ ]") {
		t.Errorf("indentation not preserved: %q", got)
	}
}

// TestRenderPlanLineMixedCaseCheckedRecognized verifies that [X] (uppercase)
// is recognized as checked, matching the behavior of [x].
func TestRenderPlanLineMixedCaseCheckedRecognized(t *testing.T) {
	got := renderPlanLine("- [X] uppercase checked", 40)
	if !strings.Contains(got, "[x]") {
		t.Errorf("uppercase [X] not recognized as checked: %q", got)
	}
}

// ── Helper ──────────────────────────────────────────────────────────────

func decodeJSONEvents(t *testing.T, raw string) []map[string]any {
	t.Helper()
	var out []map[string]any
	for _, line := range strings.Split(strings.TrimRight(raw, "\n"), "\n") {
		if line == "" {
			continue
		}
		var record map[string]any
		if err := json.Unmarshal([]byte(line), &record); err != nil {
			t.Fatalf("decode JSONL %q: %v", line, err)
		}
		out = append(out, record)
	}
	return out
}
