// TestWriteGuardEmitsJSONForFailedWrites verifies that a failed write
// (error present in ToolResult) is recorded to the failures log file
// so downstream consumers can detect and alert on write failures.
func TestWriteGuardEmitsJSONForFailedWrites(t *testing.T) {
	root := t.TempDir()
	ws := workspace.NewManager(config.Workspace{Root: root, CWD: root})
	m := &Model{
		workspace:      ws,
		debugLogPath:   filepath.Join(root, "logs", "conversations", "sess-wg.jsonl"),
	}

	m.recordWriteFailure(5,
		workspace.ToolRequest{Tool: "write_file", Path: "pkg/main.go", Description: "add entrypoint"},
		workspace.ToolResult{Tool: "write_file", Error: "permission denied"},
	)

	// The failure should be recorded to the .planning dir.
	failPath := filepath.Join(root, ".planning", "sess-wg.failures.jsonl")
	data, err := os.ReadFile(failPath)
	if err != nil {
		t.Fatalf("read failures log: %v", err)
	}
	if !strings.Contains(string(data), "permission denied") {
		t.Errorf("failure not recorded: %q", string(data))
	}
	if !strings.Contains(string(data), "write_file") {
		t.Errorf("tool not recorded: %q", string(data))
	}
}

// TestWriteGuardSuppressesSuccessfulWrites ensures a successful write
// does NOT create a failures log file.
func TestWriteGuardSuppressesSuccessfulWrites(t *testing.T) {
	root := t.TempDir()
	ws := workspace.NewManager(config.Workspace{Root: root, CWD: root})
	m := &Model{
		workspace:    ws,
		debugLogPath: filepath.Join(root, "logs", "conversations", "sess-quiet.jsonl"),
	}

	m.recordWriteSuccess(3,
		workspace.ToolRequest{Tool: "edit_file", Path: "x.go"},
		workspace.ToolResult{Tool: "edit_file", Summary: "ok"},
	)

	failPath := filepath.Join(root, ".planning", "sess-quiet.failures.jsonl")
	if _, err := os.Stat(failPath); !os.IsNotExist(err) {
		t.Fatalf("successful write should not create failures log")
	}
}

